@function_tool
def human_readable_size(bytes_count: int) -> str:
    """Convert a byte count into a friendly size string."""
    for unit in ["B", "KB", "MB", "GB"]:
        if bytes_count < 1024:
            return f"{bytes_count:.1f} {unit}"
        bytes_count /= 1024
    return f"{bytes_count:.1f} TB"
